describe('벡터: 옛 TS 구현이 낸 값과 글자까지 같다', () => {
  it.each(VECTORS)('$fn: $note', ({ fn, args, expected, undef }) => {
    const result = (IMPLS[fn] as (...a: unknown[]) => unknown)(...args);
    expect(result === undefined ? 'undefined' : JSON.stringify(result)).toBe(undef ? 'undefined' : JSON.stringify(expected));
  });
});

describe('의도한 차이(옛 TS와 다르다)', () => {
  it('짝 없는 서로게이트는 napi 경계에서 U+FFFD가 된다', () => {
    const file = discoverJsFile('a\uD800.test.ts', "it('x\uD800y', f);");
    expect(file.path).toBe('a\uFFFD.test.ts');
    expect(file.tests[0]?.name).toBe('x\uFFFDy');
  });

  it('스위트가 약 60단계를 넘게 중첩된 발견 결과는 평탄화하지 않고 던진다(JSON 읽기의 재귀 한도)', () => {
    const file = discoverJunitFile('AT.java', 'class A {\n'.repeat(80) + '@Test void t() {}\n');
    expect(() => flattenDiscoveredFile(file)).toThrow();
    // 발견은 깊이와 상관없이 끝난다
    expect(discoverJunitFile('AT.java', 'class A {\n'.repeat(20_000)).suites).toHaveLength(1);
  });

  it('requirementIds가 없는 스위트 안 테스트는 던진다', () => {
    const file = { path: 'x', framework: 'jest', suites: [{ name: 'S', displayName: 'S', line: 1, skipped: false, suites: [], tests: [{ name: 't' }] }], tests: [] };
    expect(() => flattenDiscoveredFile(file as unknown as DiscoveredFile)).toThrow();
  });

  it('평탄화 입력의 모양이 어긋나면 Error로 던진다(옛 구현은 TypeError)', () => {
    expect(() => flattenDiscoveredFile({ path: 'x', framework: 'jest', suites: [{}], tests: [] } as unknown as DiscoveredFile)).toThrow(Error);
    expect(() => flattenDiscoveredFile({ path: 'x', framework: 'jest', suites: [], tests: [{}] } as unknown as DiscoveredFile)).not.toThrow();
  });
});
